=====diff.mjs=====
// Differential comparison runner: candidate .mjs vs cached golden reference.
// Usage: node /tmp/harness/diff.mjs [/output/test2.mjs]
// Test infrastructure only.
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";

const TARGET = process.argv[2] || "/output/test2.mjs";

function run(args) {
  return new Promise((res) => {
    const p = spawn(process.execPath, [TARGET, ...args]);
    let o = "", e = "";
    p.stdout.on("data", (d) => (o += d));
    p.stderr.on("data", (d) => (e += d));
    p.on("close", (c) => res({ o, e, c }));
    p.on("error", () => res({ o: "", e: "SPAWN_ERR", c: -1 }));
  });
}

function load(f) {
  return readFileSync(f, "utf8").trim().split("\n").map((l) => JSON.parse(l));
}

const mismatches = [];
let checked = 0;

async function sweep(cases, argsOf, label) {
  let idx = 0;
  const results = new Array(cases.length);
  async function worker() {
    while (idx < cases.length) {
      const i = idx++;
      results[i] = await run(argsOf(cases[i]));
    }
  }
  await Promise.all(Array.from({ length: 24 }, worker));
  cases.forEach((g, i) => {
    const a = results[i];
    checked++;
    // Compare stdout, stderr and exit code byte-for-byte.
    if (a.o !== g.o || a.e !== g.e || a.c !== g.c) {
      mismatches.push({ label, input: argsOf(g), expected: { o: g.o, e: g.e, c: g.c }, actual: a });
    }
  });
}

await sweep(load("/tmp/harness/golden.jsonl"), (g) => ["--a", g.v], "value");
await sweep(load("/tmp/harness/golden-argv.jsonl"), (g) => g.args, "argv");

console.log(`checked ${checked}, mismatches ${mismatches.length}`);
for (const m of mismatches.slice(0, 40)) {
  console.log("---", m.label, JSON.stringify(m.input));
  console.log("  exp:", JSON.stringify(m.expected));
  console.log("  got:", JSON.stringify(m.actual));
}
if (mismatches.length > 40) console.log(`... and ${mismatches.length - 40} more`);
process.exit(mismatches.length ? 1 : 0);
