// Vector generator (test infrastructure only, NOT a deliverable).
const CHARSET="qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
const BECH32M=0x2bc830a3;
function polymod(v){let chk=1;for(const x of v){const top=chk>>>25;chk=((chk&0x1ffffff)<<5)^x;for(let i=0;i<5;i++)if((top>>>i)&1)chk^=GEN[i];chk>>>=0;}return chk>>>0;}
function hrpExp(h){const a=[],b=[];for(const c of h){a.push(c.codePointAt(0)>>5);b.push(c.codePointAt(0)&31);}return a.concat([0],b);}
export function cks(h,d,konst=1){const pm=polymod(hrpExp(h).concat(d,[0,0,0,0,0,0]))^konst;const o=[];for(let i=0;i<6;i++)o.push((pm>>>(5*(5-i)))&31);return o;}
export const enc=(h,d,konst=1)=>h+"1"+d.concat(cks(h,d,konst)).map(x=>CHARSET[x]).join("");
export const encM=(h,d)=>enc(h,d,BECH32M);
export {CHARSET};
