// Argv-level differential golden: full argument vectors, not just --a values.
// Test infrastructure only.
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const EXE = "/workspace/dataset/test2_executable";
const V = "?1ezyfcl"; // a known-valid bech32 string
const OK = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";

export const ARGV_CASES = [
  [], ["--a"], ["--a", V], ["--a=" + V], ["--a="], ["--a", ""],
  ["--a", V, "--a", OK], ["--a", OK, "--a"], ["-h"], ["--help"], ["--he"], ["--hel"], ["--h"],
  ["-h", "--a", V], ["--a", V, "-h"], ["--help", "--a", V], ["--help=x"], ["-h=x"],
  ["--a", V, "extra"], ["extra", "--a", V], ["--a", V, "extra1", "extra2"],
  ["--b", "x"], ["--b"], ["-a", V], ["-A", V], ["--A", V], ["--aa", V], ["--a-", V],
  ["--", "--a", V], ["--a", "--", V], ["--a", V, "--"], ["--", V], ["--"],
  ["--a", "-"], ["--a", "-5"], ["--a", "-0.5"], ["--a", "-.5"], ["--a", "-5x"],
  ["--a", "-1e5"], ["--a", "+5"], ["--a", "-9999999999"], ["--a", "--"], ["--a", "-h"],
  ["--a", "-x y"], ["--a", "- x"], ["--a", "--foo bar"], ["--a", "-ab"], ["--a", "--a b"],
  ["--a", "--help"], ["--a", "--a"], ["--a", "-hx"], ["--a", "--a=1"],
  ["--a", V, "--b"], ["--a", V, "-h", "extra"], ["--a", "a", "--a", "b", "--a", V],
  ["--a=--a"], ["--a=-h"], ["--a=-5"], ["--a=" + V, "extra"], ["--a", V, "--a=" + OK],
  ["-ha", V], ["-h", "-h"], ["--a", "\t"], ["--a", " "], ["--a", "A12UEL5L"],
];

function run(cmd, args) {
  return new Promise((res) => {
    const p = spawn(cmd, args);
    let o = "", e = "";
    p.stdout.on("data", (d) => (o += d));
    p.stderr.on("data", (d) => (e += d));
    p.on("close", (c) => res({ o, e, c }));
    p.on("error", () => res({ o: "", e: "SPAWN_ERR", c: -1 }));
  });
}

if (process.argv[2] === "capture") {
  const out = [];
  for (const args of ARGV_CASES) out.push({ args, ...(await run(EXE, args)) });
  writeFileSync("/tmp/harness/golden-argv.jsonl", out.map((r) => JSON.stringify(r)).join("\n") + "\n");
  console.log("captured", out.length, "argv cases");
}
export { run };
