// Emits one test vector per line (raw --a value). Infrastructure only.
import {enc, encM, CHARSET} from "./encode.mjs";
const D=n=>Array.from({length:n},(_,i)=>i%32);
const out=[];
const add=s=>out.push(s);
// 1. BIP173 official valid + invalid
for(const s of ["A12UEL5L","a12uel5l","abcdef1qpzry9x8gf2tvdw0s3jn54khce6mua7lmqqqxw",
 "split1checkupstagehandshakeupstreamerranterredcaperred2y9e3w","?1ezyfcl",
 "an83characterlonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio1tt5tgs",
 "\x201nwldj5","\x7f1axkwrx","\x801eym55h","pzry9x8gf2tvdw0s3jn54khce6mua7l","1pzry9x8gf2tvdw0s3jn54khce6mua7l",
 "x1b4n0q5v","li1dgmt3","de1lg7wt","A1G7SGD8","10a06t8","1qzzfhee","a12UEL5L","A12uEL5L",
 "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4","BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4",
 "bc1p0xlxvlhemja6c4dqv22uapctqupfhlxm9h8z3k2e72q4k9hcz7vqzk5jj0","A1LQFN3A","a1lqfn3a",
 "","1","11","a1","-","-5","-0.5","+5"]) add(s);
// 2. repr-sensitive HRPs
for(const h of ["'",'"',"\\","'\"",'"\\',"\\'","a'b","a\\b","x'y\"z","'''","\\\\","''\"\"","`","~","!","#","$","%","&","*","(",")","[","]","{","}","<",">",":",";",",",".","/","?","@","^","_","|","+","=","-"])
  { add(enc(h,[])); add(enc(h,D(3))); }
// 3. hrp length boundary 1..85
for(let n=1;n<=85;n++) add(enc("a".repeat(n),[]));
// 4. total length beyond 90
for(const n of [78,79,80,81,82,83,84,85,86,90,120,300]) add(enc("bc",D(n)));
// 5. hrp with digits / embedded '1'
for(const h of ["1","11","a1","1a","a1b","1a1","999","0","bc1","tb1x"]) { add(enc(h,[])); add(enc(h,D(4))); }
// 6. bech32m (must all fail)
for(const h of ["bc","a","tb","'"]) { add(encM(h,[])); add(encM(h,D(10))); }
// 7. corrupted checksums / short data
for(const base of [enc("bc",D(5)), enc("a",[]), enc("?",D(2))]) {
  add(base.slice(0,-1)); add(base+"q"); add(base.slice(0,-1)+"q");
  add(base.toUpperCase()); add(base[0].toUpperCase()+base.slice(1));
}
// 8. invalid data chars (b,i,o,1 not in charset) + separator edges
for(const s of ["a1qpzb","a1bbbbbb","a1iiiiii","a1oooooo","a1111111","a1qpzry","abc1","abc11","1abcdef","a1qqqqqq"]) add(s);
// 9. case mixing across hrp/data
{ const b=enc("bc",D(6)); add(b.slice(0,2).toUpperCase()+b.slice(2)); add(b.slice(0,3)+b.slice(3).toUpperCase()); }
// 10. control/high chars
for(const c of ["\x00","\x09","\x0a","\x1f","\x20","\x21","\x7e","\x7f","\x80","\xff","é","中","\u{1f600}"])
  { add(c+"1ezyfcl"); add(enc("?",[])+c); add(c); }
// 11. random ASCII 33..126 fuzz (deterministic LCG)
let seed=12345; const rnd=()=>((seed=(seed*1103515245+12345)&0x7fffffff)/0x7fffffff);
for(let i=0;i<600;i++){ const n=1+Math.floor(rnd()*40); let s=""; for(let j=0;j<n;j++) s+=String.fromCharCode(33+Math.floor(rnd()*94)); add(s); }
// 12. random valid-ish: real encode with random hrp/data then random single-char mutation
for(let i=0;i<400;i++){
  const hl=1+Math.floor(rnd()*6); let h=""; for(let j=0;j<hl;j++) h+=String.fromCharCode(33+Math.floor(rnd()*94));
  if(h.includes("1")&&rnd()<0.5) h=h.replaceAll("1","a");
  const dl=Math.floor(rnd()*20); const d=Array.from({length:dl},()=>Math.floor(rnd()*32));
  let s=enc(h,d);
  if(rnd()<0.5){ const p=Math.floor(rnd()*s.length); s=s.slice(0,p)+String.fromCharCode(33+Math.floor(rnd()*94))+s.slice(p+1); }
  add(s);
}
process.stdout.write(out.map(s=>JSON.stringify(s)).join("\n")+"\n");
